select * from explore_package

    and name like concat('%', #{name}, '%')
    and category_id = #{categoryId}
    and status = #{status}

select p.*, c.name as categoryName from explore_package p left join category c on p.category_id = c.id
and p.name like concat('%', #{name}, '%') and p.status = #{status} and p.category_id = #{categoryId}
order by p.create_time desc

mapper.update:
update explore_package
category_id = #{categoryId}, name = #{name}, price = #{price}, status = #{status}, description = #{description}, image = #{image}, duration_minutes = #{durationMinutes}, capacity = #{capacity}, booked = #{booked}, district = #{district}, address = #{address}, meeting_point = #{meetingPoint}, cancel_policy = #{cancelPolicy}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}
